            tax_transaction_id?: string;
            tax_reverse_charge?: boolean;
            tax_exempt_reason?: string;
            tax_status?: components["schemas"]["InvoiceTaxStatus"];
            /** Format: date-time */
            tax_deferred_at?: string | null;
            tax_retry_count?: number;
            tax_pending_reason?: string;
